#!/bin/bash
# ARTEMIS RESORT — ONE COMMAND INSTALLER
# Run as root: bash install_artemis.sh
set -e
echo "=== Artemis Resort Install ==="
SITE_DIR=/var/www/artemis
mkdir -p "$SITE_DIR/templates" "$SITE_DIR/static"

# Decode and write files
python3 - << 'PYEOF'
import base64
with open('/var/www/artemis/app.py','wb') as f:
    f.write(base64.b64decode(""))
print("app.py OK")
with open('/var/www/artemis/templates/index.html','wb') as f:
    f.write(base64.b64decode(""))
print("index.html OK")
PYEOF

# Venv
echo "Installing Python deps..."
python3 -m venv /var/www/artemis/venv
/var/www/artemis/venv/bin/pip install -q flask gunicorn 2>&1 | tail -2

# Systemd
cat > /etc/systemd/system/artemis.service << 'SVCEOF'
[Unit]
Description=Artemis Resort
After=network.target
[Service]
User=www-data
WorkingDirectory=/var/www/artemis
ExecStart=/var/www/artemis/venv/bin/gunicorn -w 2 -b 127.0.0.1:8082 app:app
Restart=always
[Install]
WantedBy=multi-user.target
SVCEOF

systemctl daemon-reload
systemctl enable artemis
systemctl restart artemis
sleep 2
systemctl is-active artemis && echo "artemis: RUNNING" || { echo "FAILED"; journalctl -u artemis -n 30; exit 1; }

# nginx
cat > /etc/nginx/sites-available/artemisresort.com << 'NGXEOF'
server {
    listen 80;
    server_name artemisresort.com www.artemisresort.com;
    location /static/ { alias /var/www/artemis/static/; expires 30d; }
    location / {
        proxy_pass http://127.0.0.1:8082;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }
}
NGXEOF

ln -sf /etc/nginx/sites-available/artemisresort.com /etc/nginx/sites-enabled/artemisresort.com
nginx -t && systemctl reload nginx && echo "nginx: OK"

# DB
/var/www/artemis/venv/bin/python3 -c "
import sqlite3; conn=sqlite3.connect('/var/www/artemis/leads.db')
conn.execute('CREATE TABLE IF NOT EXISTS leads (id INTEGER PRIMARY KEY, name TEXT, email TEXT, phone TEXT, amount TEXT, created_at TEXT)')
conn.commit(); conn.close(); print('DB: OK')
"
chown -R www-data:www-data /var/www/artemis/
chmod 755 /var/www/artemis/static/

echo ""
echo "========================================"
echo " DONE: http://artemisresort.com"
echo " Leads: http://artemisresort.com/admin/leads?t=rovlex2025"
echo " SSL: certbot --nginx -d artemisresort.com -d www.artemisresort.com -m ROVLEX@ROVLEX.COM --agree-tos --no-eff-email"
echo "========================================"
